// The posted-tax rate rule (shared/gst/postedRate.ts) changes ONLY ledger-line documents with a
// rate-less sales line that post CGST / SGST / IGST. Every other outward document of the corpus
// (gstParityCorpus.testutil.ts: rated / explicit-0 % / cess ledgers, SEZ / export with and without
// payment, reverse charge, notes, no tax) must come out of extractOutwardDocs and
// extractEdocInvoices exactly as before — the fixture was generated by running origin/main's
// gst.ts / edocs.ts (before the rule) over the same corpus, for a regular, a composition and an
// unregistered company. Never regenerate it to make a change pass.
import { describe, it, expect } from 'vitest'
import { readFileSync } from 'fs'
import { join } from 'path'
import { seededDb, TEST_INFO } from '../db/testdb'
import { writeCompanyInfo } from '../db/seed'
import type { DB } from '../db/connection'
import type { CompanyInfo } from '@shared/domain'
import { extractOutwardDocs, gstr1, gstr3b, gstValidate } from './gst'
import { createLedger, listLedgers } from './masters'
import { postIntent } from './simplePost'
import { dashGst } from './dashboard'
import { extractEdocInvoices } from './edocs'
import { buildParityCorpus, CORPUS_FROM, CORPUS_TO } from './gstParityCorpus.testutil'
import type { GstDoc } from '@shared/gst/returns'

const INFOS = {
  regular: TEST_INFO,
  composition: { ...TEST_INFO, gstRegistrationType: 'composition' as const },
  unregistered: { ...TEST_INFO, gstRegistrationType: 'unregistered' as const }
}
const fixture = JSON.parse(readFileSync(join(__dirname, '__fixtures__', 'gstPostedRateParity.main.json'), 'utf8')) as Record<
  keyof typeof INFOS, { docs: unknown[]; edocs: unknown[] }
>

describe('posted-tax rate — everything else unchanged (fixture from origin/main)', () => {
  const { db, changed } = buildParityCorpus()
  for (const [k, info] of Object.entries(INFOS) as [keyof typeof INFOS, typeof TEST_INFO][]) {
    it(`${k}: outward documents and e-documents equal the pre-rule output`, () => {
      const docs = extractOutwardDocs(db, info, CORPUS_FROM, CORPUS_TO).filter((d) => !changed.has(d.voucherId))
      expect(JSON.parse(JSON.stringify(docs))).toEqual(fixture[k].docs)
      const edocs = extractEdocInvoices(db, info, CORPUS_FROM, CORPUS_TO).filter((d) => !changed.has(d.voucherId ?? -1))
      expect(JSON.parse(JSON.stringify(edocs))).toEqual(fixture[k].edocs)
      expect(fixture[k].docs.length).toBe(19)
    })
  }
})

describe('posted-tax rate — the documents it changes (hand-worked)', () => {
  const { db, changed } = buildParityCorpus()
  const docs = extractOutwardDocs(db, TEST_INFO, CORPUS_FROM, CORPUS_TO).filter((d) => changed.has(d.voucherId))
  const edocs = extractEdocInvoices(db, TEST_INFO, CORPUS_FROM, CORPUS_TO).filter((d) => changed.has(d.voucherId ?? -1))
  const items = (d: GstDoc) => d.items.map((i) => [i.rate, i.taxable, i.cgst, i.sgst, i.igst, i.cess])

  it('each changed document is reported at its posted rate, values tie to the books', () => {
    // Date order: the 2025-07 documents, then the 2026-02 ones.
    expect(docs.map(items)).toEqual([
      [[18, 100000, 9000, 9000, 0, 0]], // 9 % + 9 % on 1,000
      [[28, 100000, 0, 0, 28000, 0]], // IGST 280 on 1,000 — 28 % is a slab of 2025-07 (before 22 Sep 2025)
      [[18, 100000, 9000, 9000, 0, 0], [5, 100000, 2500, 2500, 0, 0]], // 18 % ledger (180) + rate-less 1,000: 230 - 180 = 50 -> 5 %
      [[18, 100000, 0, 0, 18000, 0]], // export WITH payment of IGST
      [[18, 10000, 900, 900, 0, 0]], // outward debit note
      [[28, 100000, 14000, 14000, 0, 0]], // cess posted separately is not part of the rate
      [[5, 100000, 2500, 2500, 0, 0]], // 2026-02, B2C, no HSN
      [[18, 123456, 11111, 11111, 0, 0]], // tax rounded to the rupee (111 + 111); round off under Indirect Expenses
      [[12, 10000, 600, 600, 0, 0]] // credit note dated 2026-02 at its 2025 bill's 12 %: not off-slab
    ])
    expect(docs.every((d) => (d.nilLines ?? []).length === 0 && !d.validation?.offSlabRate)).toBe(true)
    // Booked total vs taxable + computed tax: 0, except the rupee-rounded one (posted 111 x 2 + 0.44
    // round off vs computed 111.11 x 2: -22 + 44 = +22 paise, inside the ±₹1 value check) and the
    // cess one (its ledger carries no cess rate, so the posted ₹120 cess is not reported — as before
    // the rule — and the value check blocks it).
    expect(docs.map((d) => d.validation!.valDiff)).toEqual([0, 0, 0, 0, 0, 12000, 0, 22, 0])
    expect(gstValidate(db, TEST_INFO, CORPUS_FROM, CORPUS_TO).find((i) => i.code === 'val_mismatch')!.voucherIds).toContain(docs[5]!.voucherId)
  })

  it('e-documents carry the same rates and tax heads per item', () => {
    const perRate = (rows: { rate: number; taxable: number; cgst: number; sgst: number; igst: number }[]) =>
      [...rows].sort((a, b) => a.rate - b.rate).map((r) => [r.rate, r.taxable, r.cgst, r.sgst, r.igst])
    expect(edocs.map((e) => perRate(e.items.map((i) => ({ ...i, taxable: i.taxablePaise }))))).toEqual(docs.map((d) => perRate(d.items)))
  })
})

// WP 9.2: a "just an amount" sale (simple:post `sale` with `amount` + `gstRate`) posts on the
// rate-less Sales ledger; GSTR-1, GSTR-3B and the Home GST tile (dashGst) report it at its rate.
describe('posted-tax rate — a simple "just an amount" sale and its return', () => {
  const INFO: CompanyInfo = { ...TEST_INFO, name: 'Amount Co', gstin: '27AAPFU0939F1ZV', stateCode: '27', gstRegistrationType: 'regular' }
  const TODAY = '2025-08-14' // the next GSTR-3B (20 Aug) files July
  const g = (db: DB, name: string): number => (db.prepare('SELECT id FROM groups WHERE name = ?').get(name) as { id: number }).id
  function company(): DB {
    const db = seededDb()
    writeCompanyInfo(db, INFO)
    createLedger(db, { name: 'Sales', groupId: g(db, 'Sales Accounts') })
    for (const t of ['cgst', 'sgst', 'igst'] as const) createLedger(db, { name: t.toUpperCase(), groupId: g(db, 'Duties & Taxes'), taxType: t })
    createLedger(db, { name: 'Round Off', groupId: g(db, 'Indirect Expenses') })
    createLedger(db, { name: 'Ramesh', groupId: g(db, 'Sundry Debtors'), stateCode: '27' })
    createLedger(db, { name: 'Kumar', groupId: g(db, 'Sundry Debtors'), stateCode: '29', gstin: '29AABCF9012G1ZQ' })
    return db
  }
  const id = (db: DB, name: string): number => (db.prepare('SELECT id FROM ledgers WHERE name = ?').get(name) as { id: number }).id

  it('GSTR-1, GSTR-3B and dashGst carry the sale at 18 % / 5 % and the return at the bill\'s rate', () => {
    const db = company()
    expect(listLedgers(db).find((l) => l.name === 'Sales')!.gstRate).toBeNull()
    const sale = postIntent(db, INFO, { clientId: 'amount-sale-1', kind: 'sale', customerId: id(db, 'Ramesh'), date: '2025-07-10', amount: { amount: '1,234.56', gstRate: 18 } }, TODAY)
    postIntent(db, INFO, { clientId: 'amount-sale-2', kind: 'sale', customerId: id(db, 'Kumar'), date: '2025-07-11', amount: { amount: '2,000', gstRate: 5 } }, TODAY)
    postIntent(db, INFO, { clientId: 'amount-sale-3', kind: 'return_sale', billId: sale.voucherIds[0]!, date: '2025-07-20', amount: { amount: '200' } }, TODAY)
    const from = '2025-07-01'
    const to = '2025-07-31'
    const docs = extractOutwardDocs(db, INFO, from, to)
    // 1,234.56 x 9 % = 111.1104 -> 111.11 each; 2,000 x 5 % IGST = 100; the return: 200 x 9 % = 18 each.
    expect(docs.map((d) => [d.kind, d.items.map((i) => [i.rate, i.taxable, i.cgst, i.sgst, i.igst])])).toEqual([
      ['sales', [[18, 123456, 11111, 11111, 0]]],
      ['sales', [[5, 200000, 0, 0, 10000]]],
      ['credit_note', [[18, 20000, 1800, 1800, 0]]]
    ])
    expect(docs.every((d) => (d.nilLines ?? []).length === 0 && !d.validation?.offSlabRate)).toBe(true)
    const r1 = gstr1(db, INFO, from, to, '072025')
    expect(r1.summary.find((x) => x.section === 'nil')?.taxable ?? 0).toBe(0)
    expect(r1.summary.find((x) => x.section === 'b2b')).toMatchObject({ docs: 1, taxable: 200000, igst: 10000 })
    const r3 = gstr3b(db, INFO, from, to, '072025')
    // Outward: 1,234.56 + 2,000 - 200 = 3,034.56; CGST / SGST 111.11 - 18 = 93.11; IGST 100.
    expect(r3.outward).toMatchObject({ taxable: 303456, cgst: 9311, sgst: 9311, igst: 10000 })
    expect(r3.nilExempt.taxable).toBe(0)
    const tile = dashGst(db, INFO, TODAY)!
    expect(tile.period).toBe('2025-07')
    expect(tile.outwardTax).toBe(9311 + 9311 + 10000)
    // The posted Output tax balances equal what the returns report.
    const posted = (name: string): number =>
      (db.prepare("SELECT COALESCE(SUM(CASE WHEN dr_cr = 'cr' THEN amount ELSE -amount END), 0) AS t FROM voucher_lines WHERE ledger_id = ?").get(id(db, name)) as { t: number }).t
    expect([posted('CGST'), posted('SGST'), posted('IGST')]).toEqual([9311, 9311, 10000])
  })
})
